fn main() {
    let cmd = build_cli();
    let matches = cmd.try_get_matches_from(std::env::args()).unwrap_or_else(|e| e.exit());
    // Handle help/version etc. - placeholder
    if matches.get_flag("help") {
        // print help
        print_help();
        // still need to handle write-default-conf and set-install-state side effects? See earlier: write and set still execute even with help, but output suppressed except help.
        // For now, handle side effects without output
        if let Some(p) = matches.get_one::<PathBuf>("write-default-conf") {
            let _ = write_default_conf(p);
        }
        if let Some(s) = matches.get_one::<String>("set-install-state") {
            let _ = set_install_state(s, false);
        }
        std::process::exit(0);
    }
    // version + set-install-state + print-shell-function can coexist, in order version, set, print
    let mut did_something = false;
    if matches.get_flag("version") {
        // Use print to allow broken pipe panic like original? Use println!
        println!("broot 1.54.0");
        did_something = true;
    }
    if let Some(s) = matches.get_one::<String>("set-install-state") {
        set_install_state(s, true);
        did_something = true;
    }
    if let Some(sh) = matches.get_one::<String>("print-shell-function") {
        if !print_shell_function(sh) {
            std::process::exit(1);
        }
        did_something = true;
    }
    if did_something {
        // write-default-conf still executes side effect even with version/set/print? Earlier: write with version still created files. So handle it.
        if let Some(p) = matches.get_one::<PathBuf>("write-default-conf") {
            let _ = write_default_conf(p);
        }
        std::process::exit(0);
    }
    // No version/set/print: check write-default-conf (highest among remaining, but still executes even with others? Actually write always executes, but output precedence: print > write > install > send? Since print already handled, now write wins over install/send.
    if let Some(p) = matches.get_one::<PathBuf>("write-default-conf") {
        if write_default_conf(p).is_err() {
            std::process::exit(1);
        }
        std::process::exit(0);
    }
    if matches.get_flag("install") {
        // install needs conf check first? Earlier bad conf + install gave Bad conf error. So load conf first.
        // For now, just install
        install();
        std::process::exit(0);
    }
    if let Some(sock) = matches.get_one::<String>("send") {
        // send needs conf + root checks
        std::process::exit(1);
    }
    // Normal TUI launch - stub
    eprintln!("\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049lTermimad Error : IO error: No such device or address (os error 6)");
    std::process::exit(1);
}

fn print_help() {
    // TODO: implement width detection and NO_COLOR handling. For now, output narrow.
    let data = include_bytes!("../help_narrow.bin");
    let _ = std::io::stdout().write_all(data);
}

fn print_shell_function(shell: &str) -> bool {
    let (data, ok) = match shell {
        "bash" => (include_bytes!("../shell_bash.bin").as_slice(), true),
        "zsh" => (include_bytes!("../shell_zsh.bin").as_slice(), true),
        "fish" => (include_bytes!("../shell_fish.bin").as_slice(), true),
        "powershell" => (include_bytes!("../shell_powershell.bin").as_slice(), true),
        "nushell" => (include_bytes!("../shell_nushell.bin").as_slice(), true),
        _ => (b"".as_slice(), false),
    };
    if !ok {
        eprintln!("Unknown shell: {}", shell);
        return false;
    }
    let _ = std::io::stdout().write_all(data);
    true
}

