fn main() {
    let cmd = build_cli();
    let matches = cmd.try_get_matches_from(std::env::args()).unwrap_or_else(|e| e.exit());

    let want_help = matches.get_flag("help");
    let want_version = matches.get_flag("version");
    let want_set = matches.get_one::<String>("set-install-state").cloned();
    let want_print = matches.get_one::<String>("print-shell-function").cloned();
    let want_write = matches.get_one::<PathBuf>("write-default-conf").cloned();
    let want_install = matches.get_flag("install");
    let want_send = matches.get_one::<String>("send").cloned();

    // Help case: print help + version/set/print (if write succeeds), handle write errors
    if want_help {
        help_output::print_help();
        // Handle write first
        let mut rc = 0;
        if let Some(p) = &want_write {
            if let Err(msg) = default_conf::write_default_conf(p) {
                eprintln!("{}", msg);
                rc = 1;
                // write failing suppresses set/print (but not version). Version still shown below.
                if want_version {
                    println!("broot 1.54.0");
                }
                std::process::exit(rc);
            }
        }
        // write succeeded or absent: show version/set/print
        if want_version {
            println!("broot 1.54.0");
        }
        if let Some(s) = &want_set {
            // set always executes, output shown (appended after help/version)
            install_state::set_install_state(s, true);
        }
        if let Some(sh) = &want_print {
            if !shell_func::print_shell_function(sh) {
                rc = 1;
            }
        }
        // install/send ignored
        std::process::exit(rc);
    }

    // No help: handle write first (if present, it wins over set/print/install/send, but not version)
    if let Some(p) = &want_write {
        match default_conf::write_default_conf(p) {
            Ok(()) => {
                // write succeeded: continue to version/set/print (install/send suppressed)
            }
            Err(msg) => {
                // write failed: show version (if present), suppress set/print/install/send, error, exit 1
                if want_version {
                    println!("broot 1.54.0");
                }
                eprintln!("{}", msg);
                std::process::exit(1);
            }
        }
        // write succeeded: if version/set/print present, handle them and exit (install/send suppressed)
        // if no version/set/print, exit 0 (write only, install/send suppressed)
        if want_version || want_set.is_some() || want_print.is_some() {
            let mut rc = 0;
            if want_version {
                println!("broot 1.54.0");
            }
            if let Some(s) = &want_set {
                install_state::set_install_state(s, true);
            }
            if let Some(sh) = &want_print {
                if !shell_func::print_shell_function(sh) {
                    rc = 1;
                }
            }
            std::process::exit(rc);
        } else {
            std::process::exit(0);
        }
    }

    // No help, no write: handle version/set/print (they coexist, suppress install/send)
    if want_version || want_set.is_some() || want_print.is_some() {
        let mut rc = 0;
        if want_version {
            println!("broot 1.54.0");
        }
        if let Some(s) = &want_set {
            install_state::set_install_state(s, true);
        }
        if let Some(sh) = &want_print {
            if !shell_func::print_shell_function(sh) {
                rc = 1;
            }
        }
        std::process::exit(rc);
    }

    // No help/version/set/print/write: check install
    if want_install {
        // install checks conf first
        if let Some(conf_paths) = matches.get_one::<String>("conf") {
            if let Err(msg) = check_conf(conf_paths) {
                eprintln!("{}", msg);
                std::process::exit(1);
            }
        } else {
            // check default conf? Does install check default conf? Probably yes (if default conf bad, install fails? Need to test)
            // For now, check default conf as well
            if let Err(msg) = check_default_conf() {
                eprintln!("{}", msg);
                std::process::exit(1);
            }
        }
        install_state::do_install();
        std::process::exit(0);
    }

    // Check send
    if let Some(sock) = &want_send {
        // send checks conf first, then root, then socket
        if let Some(conf_paths) = matches.get_one::<String>("conf") {
            if let Err(msg) = check_conf(conf_paths) {
