    let _ = std::io::stdout().write_all(&data);
}

fn replace_colors(data: &[u8]) -> Vec<u8> {
    // Replace \x1b[(48;5;\d+|38;5;\d+|49|39)m with \x1b[m
    // Manual to avoid regex dep in this path (or use regex crate)
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if data[i] == 0x1b && i+1 < data.len() && data[i+1] == b'[' {
            // find 'm'
            if let Some(j) = data[i..].iter().position(|&b| b == b'm') {
                let seq = &data[i..i+j+1];
                // seq is \x1b[...m, inner is seq[2..len-1]
                let inner = &seq[2..seq.len()-1];
                let inner_str = String::from_utf8_lossy(inner);
                let is_color = inner_str == "49" || inner_str == "39"
                    || inner_str.starts_with("48;5;") || inner_str.starts_with("38;5;");
                if is_color {
                    out.extend_from_slice(b"\x1b[m");
                    i += j+1;
                    continue;
                }
            }
        }
        out.push(data[i]);
        i += 1;
    }
    out
}
