fn escape_context(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            _ => out.push(c),
        }
    }
    out
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    col: usize,
}
impl Parser {
    fn new(s: &str) -> Self { Self { chars: s.chars().collect(), pos: 0, line: 1, col: 1 } }
    fn eof(&self) -> bool { self.pos >= self.chars.len() }
    fn peek(&self) -> Option<char> { self.chars.get(self.pos).copied() }
    fn peek_next(&self, n: usize) -> Option<char> { self.chars.get(self.pos+n).copied() }
    fn consume(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied()?;
        self.pos += 1;
        if c == '\n' { self.line += 1; self.col = 1; } else { self.col += 1; }
        Some(c)
    }
    fn context(&self) -> String { self.chars[self.pos..].iter().take(15).collect() }
    fn skip_ws_comments(&mut self) -> Result<(), HjsonError> {
        loop {
            while let Some(c) = self.peek() {
