            if self.peek()==Some('/')&&self.peek_next(1)==Some('/') {
                self.consume(); self.consume();
                while let Some(c)=self.peek() { if c=='\n' {break;} self.consume(); }
                continue;
            }
            if self.peek()==Some('/')&&self.peek_next(1)==Some('*') {
                self.consume(); self.consume();
                loop {
                    if self.eof() { return Err(HjsonError{kind:"Eof".into(),line:self.line,col:self.col,context:self.context()}); }
                    if self.peek()==Some('*')&&self.peek_next(1)==Some('/') { self.consume(); self.consume(); break; }
                    self.consume();
                }
                continue;
            }
            break;
        }
        Ok(())
    }
}

