fn ensure_default_conf() -> Result<(), String> {
    let cfg = paths::config_dir();
    let conf_hjson = cfg.join("conf.hjson");
    let conf_toml = cfg.join("conf.toml");
    // If conf.hjson exists (file), use it (ignore toml), no creation. If exists but is dir, error Is a directory.
    // Else if conf.toml exists, use it, no creation. Else (neither exists), create default with message.
    if conf_hjson.exists() {
        if conf_hjson.is_dir() {
            return Err("IO Error : Is a directory (os error 21)".to_string());
        }
        // Exists as file, no creation, return Ok (parsing checked later in check_default_conf_parsing)
        return Ok(());
    }
    if conf_toml.exists() {
        if conf_toml.is_dir() {
            return Err("IO Error : Is a directory (os error 21)".to_string());
        }
        return Ok(());
    }
    // Neither exists: create default
    if let Err(e) = default_conf::write_default_conf(&cfg) {
        return Err(e);
