    let want_send = matches.get_one::<String>("send").cloned();
    let want_conf = matches.get_one::<String>("conf").cloned();

    if want_help {
        help_output::print_help();
        let mut rc = 0;
        if let Some(p) = &want_write {
            if let Err(msg) = default_conf::write_default_conf(p) {
                eprintln!("{}", msg);
                rc = 1;
                if want_version { println!("broot 1.54.0"); }
                std::process::exit(rc);
            }
        }
        if want_version { println!("broot 1.54.0"); }
        if let Some(s) = &want_set { install_state::set_install_state(s, true); }
        if let Some(sh) = &want_print { if !shell_func::print_shell_function(sh) { rc = 1; } }
        std::process::exit(rc);
    }

    if let Some(p) = &want_write {
        match default_conf::write_default_conf(p) {
            Ok(()) => {},
            Err(msg) => {
                if want_version { println!("broot 1.54.0"); }
                eprintln!("{}", msg);
                std::process::exit(1);
            }
        }
        if want_version || want_set.is_some() || want_print.is_some() {
            let mut rc = 0;
            if want_version { println!("broot 1.54.0"); }
            if let Some(s) = &want_set { install_state::set_install_state(s, true); }
            if let Some(sh) = &want_print { if !shell_func::print_shell_function(sh) { rc = 1; } }
            std::process::exit(rc);
        } else {
            std::process::exit(0);
        }
    }

    if want_version || want_set.is_some() || want_print.is_some() {
        let mut rc = 0;
        if want_version { println!("broot 1.54.0"); }
        if let Some(s) = &want_set { install_state::set_install_state(s, true); }
        if let Some(sh) = &want_print { if !shell_func::print_shell_function(sh) { rc = 1; } }
        std::process::exit(rc);
    }

    // Install without --conf: ignore default conf, just install
    // Install with --conf: ignore install flag, treat as TUI (fall through to TUI/send logic)
    if want_install && want_conf.is_none() {
        install_state::do_install();
        std::process::exit(0);
    }
    // If install with conf, ignore install (fall through). Need to clear want_install for later? Just proceed as if no install.

    // For send/TUI: handle conf, install prompt, default creation, root, etc.
    let is_send = want_send.is_some();

    // If custom conf provided: check it, skip install prompt and default creation
    if let Some(conf_paths) = &want_conf {
        if let Err(msg) = conf::check_conf_paths(conf_paths) {
            eprintln!("{}", msg);
            std::process::exit(1);
        }
        // Custom conf skips install check and default creation. Check root, then proceed.
        let root = matches.get_one::<PathBuf>("ROOT").cloned().unwrap_or_else(|| PathBuf::from("."));
        if let Err(msg) = check_root(&root) {
            eprintln!("{}", msg);
            std::process::exit(1);
        }
        if is_send {
            // Send with custom conf: try socket (no install check, no default creation)
            do_send(want_send.as_ref().unwrap(), &matches);
            std::process::exit(1); // do_send exits? Actually it should exit with appropriate code. For now, it always fails with socket error for nonexistent.
        } else {
            // TUI with custom conf: skip install, go to TUI
            let code = do_tui(&matches);
            std::process::exit(code);
        }
    }

    // No custom conf: handle install prompt (if undefined and BR_INSTALL != no)
    if should_prompt_install() {
        // Print prompt to stdout, read stdin
        if handle_install_prompt() {
            // User chose Y (install): install and exit 0 (do not proceed to TUI/send)
            std::process::exit(0);
        } else {
            // User chose N (refuse): create refused file, print refused message, continue to default creation + TUI/send (do not exit)
            // Refused file already created in handle_install_prompt? Or create here? Let's create in handle.
            // Continue (do not exit)
        }
    }

    // Ensure default conf (if missing, create with message to stdout)
    if let Err(msg) = ensure_default_conf() {
        eprintln!("{}", msg);
        std::process::exit(1);
    }
    // Check default conf parsing (if bad, error)
    if let Err(msg) = check_default_conf_parsing() {
        eprintln!("{}", msg);
        std::process::exit(1);
    }

    // Check root
    let root = matches.get_one::<PathBuf>("ROOT").cloned().unwrap_or_else(|| PathBuf::from("."));
    if let Err(msg) = check_root(&root) {
        eprintln!("{}", msg);
        std::process::exit(1);
    }

    if is_send {
        do_send(want_send.as_ref().unwrap(), &matches);
        std::process::exit(1);
    } else {
        let code = do_tui(&matches);
        std::process::exit(code);
    }
}

fn check_root(path: &PathBuf) -> Result<(), String> {
    match std::fs::metadata(path) {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("IO Error : {}", e)),
    }
}

fn should_prompt_install() -> bool {
    if std::env::var_os("BR_INSTALL").map(|v| v=="no").unwrap_or(false) {
        return false;
    }
    // Check install state: if installed or refused, no prompt. If undefined (neither file exists), prompt.
    let cfg = paths::config_dir();
    let launcher = cfg.join("launcher");
    let installed = launcher.join("installed-v4");
    let refused = launcher.join("refused");
    if installed.exists() || refused.exists() {
        return false;
    }
    true
}

fn handle_install_prompt() -> bool {
    // Returns true if installed (Y, should exit), false if refused (N, should continue)
    // Print prompt to stdout (with colors, narrow/wide? For now narrow + NO_COLOR handling)
    print_install_prompt();
    // Flush stdout to ensure prompt shown before reading stdin
    use std::io::Write;
    let _ = std::io::stdout().flush();
    // Read one line from stdin
    let mut line = String::new();
    // Use stdin read_line; if EOF (0 bytes, no input, e.g., DEVNULL), treat as Y (empty)
    // If stdin is not available (e.g., closed), read_line returns Ok(0) (EOF) -> treat as Y.
    match std::io::stdin().read_line(&mut line) {
        Ok(0) => {
            // EOF, treat as Y
            do_prompt_install();
            return true;
        }
        Ok(_) => {
            let trimmed = line.trim();
            // If starts with n/N (case-insensitive? What about "no", "No", "N", "n"? Original: n/N refuse, others (including empty, y, Y, foo) install. Check: empty (just \n, trimmed "") -> install (Y). "n" -> refuse, "N" -> refuse, "no"? Likely refuse (starts with n). "foo" -> install. Good.
            if trimmed.starts_with('n') || trimmed.starts_with('N') {
                // Refuse: create refused file (silently, no Removing output? Since undefined, no old files, so no Removing anyway), print refused message, return false (continue)
                let cfg = paths::config_dir();
                let launcher = cfg.join("launcher");
                let _ = std::fs::create_dir_all(&launcher);
                let refused = launcher.join("refused");
                let content = "\nThis file tells broot you refused the installation of the companion shell function.\nIf you want to install it run\n    broot -- install\n";
                let _ = std::fs::write(&refused, content);
                print_refused_message();
                return false;
            } else {
                // Install (Y, empty, y, foo, etc.)
                do_prompt_install();
                return true;
            }
        }
        Err(_) => {
            // Read error, treat as Y?
            do_prompt_install();
            return true;
        }
    }
}

fn is_nocolor() -> bool {
    if let Some(v) = std::env::var_os("NO_COLOR") { !v.is_empty() } else { false }
}
fn code_style(s: &str) -> String {
    if is_nocolor() { format!("\x1b[m\x1b[m{}\x1b[m\x1b[m", s) } else { format!("\x1b[48;5;234m\x1b[38;5;250m{}\x1b[49m\x1b[39m", s) }
}
fn pink_italic(s: &str) -> String {
    if is_nocolor() { format!("\x1b[m\x1b[3m{}\x1b[0m", s) } else { format!("\x1b[38;5;13m\x1b[3m{}\x1b[0m", s) }
}
