fn ensure_default_conf() -> Result<(), String> {
    let cfg = paths::config_dir();
    let conf_hjson = cfg.join("conf.hjson");
    let conf_toml = cfg.join("conf.toml");
    // If conf.hjson exists (file), use it (ignore toml), no creation. If exists but is dir, error Is a directory.
    // Else if conf.toml exists, use it, no creation. Else (neither exists), create default with message.
    if conf_hjson.exists() {
        if conf_hjson.is_dir() {
            return Err("IO Error : Is a directory (os error 21)".to_string());
        }
        // Exists as file, no creation, return Ok (parsing checked later in check_default_conf_parsing)
        return Ok(());
    }
    if conf_toml.exists() {
        if conf_toml.is_dir() {
            return Err("IO Error : Is a directory (os error 21)".to_string());
        }
        return Ok(());
    }
    // Neither exists: create default
    if let Err(e) = default_conf::write_default_conf(&cfg) {
        return Err(e);
    }
    // Print message to stdout: New Configuration files written in "<config>"... with bold for path
    println!("New Configuration files written in {}.", bold(&format!("{:?}", cfg.to_string_lossy())));
    println!("You should have a look at them: their comments will help you configure broot.");
    println!("You should especially set up your favourite editor in verbs.hjson.");
    Ok(())
}

fn check_default_conf_parsing() -> Result<(), String> {
    let cfg = paths::config_dir();
    let conf_hjson = cfg.join("conf.hjson");
    let conf_toml = cfg.join("conf.toml");
    if conf_hjson.exists() && !conf_hjson.is_dir() {
        // Check hjson file (ignore toml even if exists, hjson takes precedence)
        return conf::check_conf_paths(&conf_hjson.to_string_lossy());
    }
    if conf_toml.exists() && !conf_toml.is_dir() {
        return conf::check_conf_paths(&conf_toml.to_string_lossy());
    }
    // Neither exists? Should have been created in ensure_default_conf (which would have created hjson). If still neither (e.g., creation failed? No, ensure would have errored). Good - return Ok.
    Ok(())
}

