fn do_tui(matches: &clap::ArgMatches) -> i32 {
    // Build TuiConfig from matches + conf values (default_flags, etc. - for now ignore conf values, just CLI flags)
    // Check if stderr is tty, if not, print Termimad error and return 1 (as tui::run_tui does)
    // For now, call tui::run_tui with minimal config
    use std::path::PathBuf;
    let root = matches.get_one::<PathBuf>("ROOT").cloned().unwrap_or_else(|| PathBuf::from("."));
    let cfg = tui::TuiConfig {
        root,
        show_hidden: matches.get_flag("hidden"),
        show_sizes: matches.get_flag("sizes"),
        show_dates: matches.get_flag("dates"),
        show_perms: matches.get_flag("permissions"),
        only_folders: matches.get_flag("only-folders"),
        show_ignored: matches.get_flag("git-ignored"),
        sort_by_size: matches.get_flag("sort-by-size"),
        sort_by_date: matches.get_flag("sort-by-date"),
        sort_by_count: matches.get_flag("sort-by-count"),
        sort_by_type: matches.get_flag("sort-by-type") || matches.get_flag("sort-by-type-dirs-first") || matches.get_flag("sort-by-type-dirs-last"),
        sort_type_dirs_first: matches.get_flag("sort-by-type-dirs-first") || matches.get_flag("sort-by-type"),
        no_sort: matches.get_flag("no-sort"),
        show_root_fs: matches.get_flag("show-root-fs"),
        max_depth: matches.get_one::<u16>("max-depth").copied(),
        trim_root: matches.get_flag("trim-root"),
        no_tree: matches.get_flag("no-tree"),
        tree: matches.get_flag("tree"),
        whale: matches.get_flag("whale-spotting"),
        git_status: matches.get_flag("git-status"),
        show_git: matches.get_flag("show-git-info"),
        color: matches.get_one::<String>("color").cloned().unwrap_or_else(|| "auto".to_string()),
        height: matches.get_one::<u16>("height").copied(),
        outcmd: matches.get_one::<PathBuf>("outcmd").cloned(),
        verb_output: matches.get_one::<PathBuf>("verb-output").cloned(),
        cmd: matches.get_one::<String>("cmd").cloned(),
        listen: matches.get_one::<String>("listen").cloned(),
        listen_auto: matches.get_flag("listen-auto"),
    };
    tui::run_tui(cfg)
}
