    // Simplify: First, compute sizes/counts for all paths via full walk (including hidden/ignored, no max_depth, no only_folders, no filtering? Filtering (pattern) also doesn't affect sizes/counts (total). Good - full walk for sizes/counts.
    // Then, build display tree (pruned for display flags + max_depth, but with sizes/counts from full maps).
    let mut size_map: HashMap<PathBuf, u64> = HashMap::new();
    let mut count_map: HashMap<PathBuf, usize> = HashMap::new();
    compute_sizes_counts(root, &mut size_map, &mut count_map);
    build_display_tree(root, show_hidden, only_folders, max_depth, show_ignored, &size_map, &count_map, 0)
}

fn compute_sizes_counts(path: &Path, size_map: &mut HashMap<PathBuf, u64>, count_map: &mut HashMap<PathBuf, usize>) -> (u64, usize) {
    // Returns (disk_sum, count) for subtree rooted at path, including itself? For files: disk = blocks*512 (via symlink_metadata? For symlinks, what disk? Use lstat blocks? Or 0? For symlinks, size? Probably lstat size (target length) for apparent? And disk? For symlinks, blocks? On Linux, symlink blocks? Possibly 0? Let's use symlink_metadata for symlinks (don't follow), metadata for others? For symlinks to dirs, don't descend (as per broot: symlinks to dirs not entered unless selected? For sizes, do symlinked dirs' contents count towards parent dir disk sum? Probably not (since not entered). Good - for symlinks, don't descend, count as file (count 1, disk = lstat blocks*512? Or 0?).
    // For regular files: disk = blocks*512 (via metadata (follows? For symlinks, use lstat, not follow). Count 1.
    // For dirs (not symlink, real dir): disk = sum of children disks (files + subdirs, including hidden/ignored, no max_depth limit, no only_folders filter? Include all files/dirs, including hidden/ignored? Yes, for sizes/counts total. Good. Count = 1 (itself) + sum children counts.
    // Need to handle hidden/ignored? Include all (don't filter hidden/ignored for sizes/counts). Good - walk all entries via read_dir (which includes hidden? Yes, read_dir includes dotfiles. Good. For ignored (gitignored), read_dir includes them as well (since ignored is just .gitignore rules, not hidden from FS). Good - include all.
    // Handle symlinks: Use symlink_metadata to check file_type. If symlink, don't descend (even if target is dir), count 1, disk = lstat blocks*512? Or 0? Let's use lstat blocks.
    // For other dirs/files, use metadata (follows? For symlink to file, symlink_metadata already handled as symlink, not here. Good.)
    let sym_md = match std::fs::symlink_metadata(path) {
        Ok(md) => md,
        Err(_) => {
            size_map.insert(path.to_path_buf(), 0);
            count_map.insert(path.to_path_buf(), 1);
            return (0, 1);
        }
    };
    if sym_md.file_type().is_symlink() {
        // Symlink: don't descend, count 1, disk = blocks*512? Use symlink_metadata blocks.
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            let disk = (sym_md.blocks() as u64) * 512;
            size_map.insert(path.to_path_buf(), disk);
            count_map.insert(path.to_path_buf(), 1);
            return (disk, 1);
        }
        #[cfg(not(unix))]
        {
            size_map.insert(path.to_path_buf(), 0);
            count_map.insert(path.to_path_buf(), 1);
            return (0, 1);
        }
    }
    if sym_md.is_dir() {
        // Real dir (not symlink): walk children (all, including hidden/ignored, no filtering)
        let mut total_disk: u64 = 0;
        let mut total_count: usize = 1; // itself
        if let Ok(rd) = std::fs::read_dir(path) {
            for e in rd.flatten() {
                let child = e.path();
                let (c_disk, c_count) = compute_sizes_counts(&child, size_map, count_map);
                total_disk += c_disk;
                total_count += c_count;
            }
        }
        // Dir's own disk overhead? On overlay, dirs blocks 0, disk 0. On other FS, dirs have blocks (4096)? Should dir's own blocks count towards its disk sum? For /tmp/size_100 (single file 100 bytes, disk 4096 for file, dir blocks 0? Actually /tmp/size_100 dir blocks? On overlay, dirs blocks 0. Total disk for root = file disk 4096 + dir overhead 0 =4096. Displayed root 4096 matches. Good - dir overhead 0 (since blocks 0). On other FS where dirs have blocks (e.g., ext4, dir blocks 8, disk 4096), would root include dir overhead? Possibly yes (since blocks*512 includes dir's own blocks? For compute_sizes_counts for dir, we sum children disks only, not dir's own blocks. Should we include dir's own blocks? For overlay (blocks 0), no difference (0). For ext4 (blocks 8, 4096), dir overhead 4096 would be included? Let's check: On ext4, empty dir (no children) with -s: what size shown? Earlier empty dir /tmp/empty_s/empty_sub (empty, no children) with -s showed 0 (not 4096). Good - empty dir shows 0, not 4096 (dir overhead). So dir overhead NOT included (only files disk sum, not dir blocks). Perfect - our implementation (sum children disks only, not dir's own blocks) matches (empty dir 0). Good.
        size_map.insert(path.to_path_buf(), total_disk);
        count_map.insert(path.to_path_buf(), total_count);
        return (total_disk, total_count);
    } else {
        // Regular file (not dir, not symlink): disk = blocks*512, count 1
        #[cfg(unix)]
        {
            use std::os::unix::fs::MetadataExt;
            // Use metadata (follows? Already know not symlink, so metadata == symlink_metadata? Use sym_md (which is symlink_metadata, but for regular file, same as metadata). Good.
            let disk = (sym_md.blocks() as u64) * 512;
            size_map.insert(path.to_path_buf(), disk);
            count_map.insert(path.to_path_buf(), 1);
            return (disk, 1);
        }
        #[cfg(not(unix))]
        {
            size_map.insert(path.to_path_buf(), sym_md.len());
            count_map.insert(path.to_path_buf(), 1);
            return (sym_md.len(), 1);
        }
    }
}

