pub fn matches(pattern: &Pattern, subpath: &str, name: &str, path: &std::path::Path) -> bool {
    match pattern {
        Pattern::Empty => true,
        Pattern::FuzzyPath(pat) => fuzzy_match(pat, subpath),
        _ => false,
    }
}

fn fuzzy_match(pat: &str, text: &str) -> bool {
    // Case-insensitive subsequence: pat chars in order in text (not necessarily consecutive)
    let pat_lower = pat.to_lowercase();
    let text_lower = text.to_lowercase();
    let mut pat_chars = pat_lower.chars();
    let mut cur = pat_chars.next();
    for c in text_lower.chars() {
        if Some(c) == cur {
            cur = pat_chars.next();
            if cur.is_none() { return true; }
        }
    }
    cur.is_none()
}
